//! CM44 wraps an exact saved categorical tensor. Original records and input
//! layout are regenerated by the unchanged suite, with no target-based routing.
use super::*;

pub(crate) fn original_records(
    source: &tagged::Model,
    task: &data::Task,
) -> Result<Vec<records::Record>> {
    let train = task
        .splits
        .get("train")
        .ok_or("missing original training records")?;
    if source.n != task.vocab || source.vocab != task.vocab || train.is_empty() {
        return Err("source and original pair vocabulary differ".into());
    }
    validate_examples(train, task.vocab)?;
    Ok(train
        .iter()
        .enumerate()
        .map(|(id, e)| records::Record {
            id,
            cell: e.tokens[1] as usize + source.n * e.tokens[0] as usize,
            label: e.targets[1] as usize,
        })
        .collect())
}

fn validate_examples(examples: &[data::Example], vocab: usize) -> Result<()> {
    if examples.is_empty()
        || examples.iter().any(|e| {
            e.tokens.len() != 2
                || e.targets.len() != 2
                || e.targets[0] != -100
                || e.targets[1] < 0
                || e.targets[1] as usize >= vocab
                || !e.prompt.is_empty()
                || e.tokens.iter().any(|&t| t < 0 || t as usize >= vocab)
        })
    {
        return Err("original examples outside fixed pair layout".into());
    }
    Ok(())
}

pub(crate) fn construct(
    source: tagged::Model,
    task: &data::Task,
    entry: &Value,
) -> Result<head::Model> {
    let records = original_records(&source, task)?;
    let records_sha = head::digest(&records)?;
    let gradient = entry["source_gradient_training_run"]
        .as_bool()
        .ok_or("missing actual source training metadata")?;
    let endpoint = head::Endpoint {
        mode: import::mode(&entry["training_mode"])?,
        source_reference: entry["reference"]
            .as_str()
            .ok_or("missing source reference")?
            .to_owned(),
        source_gradient_training_run: gradient,
        source_optimizer_updates: if gradient { None } else { Some(0) },
    };
    head::Model::new(
        source,
        records,
        endpoint,
        entry["source_model_sha256"]
            .as_str()
            .ok_or("missing external source hash")?,
        &records_sha,
    )
}

pub(crate) fn forecast(model: &head::Model, task: &data::Task) -> Result<u64> {
    let mut calls = 0u64;
    for examples in task.splits.values() {
        validate_examples(examples, task.vocab)?;
        for e in examples {
            calls += 1 + u64::from(e.field.is_some());
        }
    }
    // Both the old source replay and new cached-product predictions are charged.
    let work = calls * 64 * (task.vocab + 10) as u64;
    if work + model.bounds().construction_scalar_work > head::WORK_CAP {
        return Err("original source/head metrics exceed the complete work forecast".into());
    }
    Ok(work)
}

pub(crate) fn info(model: &head::Model) -> Value {
    json!({"binding":model.binding(),"selection":model.selection(),"bounds":model.bounds(),
        "endpoint":model.endpoint(),"radius":model.radius(),"n":model.source().n,
        "q":model.source().q,"vocabulary":model.source().vocab,
        "new_gradient_batches":0,"unseen_labels_identified":false})
}
